-- 1.3.1_UndergroundWaterwaySpawns_rollback.sql
--
-- Undo db/migrations/1.3.1_UndergroundWaterwaySpawns.sql: zone 1001 gets its previous MonsterList and
-- EventMonsterList back, byte for byte (hex literals, because the old lists carry CP949 comments).
-- NOT a migration - run by hand, then restart the gameserver:
--     mysql --default-character-set=utf8mb4 -h 127.0.0.1 -u elcastle -p DARKEDEN < db/rollback/1.3.1_UndergroundWaterwaySpawns_rollback.sql
-- The client minimap file is separate: take slayers_training.mip back out of Release\Data\map (the
-- published darkeden.dpk still holds the old one).
-- Removes the 1.3.1 SchemaVersion row; deploy_db.py would re-apply it unless the file is removed first.

SET NAMES utf8mb4;

UPDATE `ZoneInfo`
   SET `MonsterList` = X''
 WHERE `ZoneID` = 1001
   AND `MonsterList` LIKE '#Hoble lv35 %';

UPDATE `ZoneInfo`
   SET `EventMonsterList` = X'0D0A090923BFC0B7B920283636302C31302C31290D0A090923C4A1C7C1C5B0B5E52028203536372C31302C31383030290D0A090923C4A1C7C1C5CDB4D7BCD2BFEF2028203536362C31302C31383030290D0A090923C4A1C7C1BECBC4AD2028203537302C312C31383030290D0A0909'
 WHERE `ZoneID` = 1001
   AND `EventMonsterList` LIKE '#Ore %';

DELETE FROM `SchemaVersion` WHERE `Major` = 1 AND `Minor` = 3 AND `Bug` = 1;
